span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;40&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;41&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;42&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;43&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;44&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;45&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Aside&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 侧边栏&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;aside:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# Values: about (info card), newestPost (latest article), allInfo (website information), flip (official account QR code), newest_comment (latest comment)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# 值: about(信息卡), newestPost(最新文章), allInfo(网站信息), flip(官方账号二维码), newest_comment(最新评论)，rewards(赞赏)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# Sticky: Fixed position / noSticky: Not fixed position&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# Sticky: 固定位置 / noSticky: 不固定位置&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;home:&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# on the homepage&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;noSticky:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;about,rewards&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;Sticky:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;love,likeme,allInfo&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;post:&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# on the article page&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;noSticky:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;about&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;Sticky:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;rewards,flip,newestPost,likeme&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;page:&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# on the page&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;noSticky:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;about&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;Sticky:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;rewards,flip,likeme&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# 菜单栏位置(0: 左 1: 右)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;position:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# Sidebar positioning(0: left 1: right)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# ...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# Reward&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# 打赏&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;award:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;enable:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;appreciators:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/reward/&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# Reward page&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# Reward Title&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 打赏标题&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;title:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;感谢您的赞赏&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# Thanks for your appreciation. / 感谢您的赞赏&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;desc:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;由于您的支持，我才能够实现写作的价值。&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;# Because of your support, I realize the value of writing articles. / 由于您的支持，我才能够实现写作的价值。&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# Reward list&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;# 打赏列表&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;list:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;comment&#34;&gt;# - name: Github Sponsor&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;comment&#34;&gt;#   qcode: https://s3.qjqq.cn/47/661ba900c4bc1.webp!color&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;comment&#34;&gt;#   url: https://github.com/sponsors/everfu&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;comment&#34;&gt;#   color: var(--efu-black)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;微信&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;qcode:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/images/wxm.webp&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;url:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/images/wxm_l.webp&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;color:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;var(--efu-green)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;name:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;支付宝&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;qcode:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/images/zfbm.webp&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;url:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;/images/zfbm_l.webp&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;attr&#34;&gt;color:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;var(--efu-blue)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/li&gt;&lt;li&gt;完成，再次感谢&lt;a href=&#34;https://blog.liushen.fun/posts/deffcde0/&#34;&gt;LiuShen&lt;/a&gt;的大力支持！&lt;/li&gt;&lt;/ol&gt;&lt;/div&gt;&lt;div class=&#34;tab-pane&#34; id=&#34;zscbl-3&#34;&gt;&lt;table&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;原帖&lt;/th&gt;&lt;th&gt;作者&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td&gt;Butterfly主题实现赞赏页面及侧边卡片&lt;/td&gt;&lt;td&gt;&lt;a href=&#34;https://blog.liushen.fun/posts/deffcde0/&#34;&gt;LiuShen&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;
              &lt;/div&gt;
            &lt;/details&gt;

&lt;h1 id=&#34;结尾&#34;&gt;&lt;a href=&#34;#结尾&#34; class=&#34;headerlink&#34; title=&#34;结尾&#34;&gt;&lt;/a&gt;结尾&lt;/h1&gt;&lt;p&gt;至此，全篇结束。希望对你有所帮助，有任何问题请在下方留言。可以关注我的 &lt;a href=&#34;/rss/&#34;&gt;公众号以及订阅我的文章&lt;/a&gt; ，感谢你的支持，是对我最大的动力，当然了，更多的是因为热爱。&lt;/p&gt;

 &lt;h1 id=&#34;前言&#34;&gt;&lt;a href=&#34;#前言&#34; class=&#34;headerlink&#34; title=&#34;前言&#34;&gt;&lt;/a&gt;前言&lt;/h1&gt;&lt;p&gt;本来是一直在用百度统计的，也不知道它抽什么风，就说我的网站违规了，真的莫名其妙。我啥都没干，搞我心态，就这样了后面我换了 &lt;a href=&#34;https://v6.51.la/&#34;&gt;51&lt;/a&gt; ，换了51la感觉还是不好，数据保留不了很久，百度和51LA好像都只有 &lt;code&gt;3年&lt;/code&gt; 。偶然的一次机会下接触到 &lt;a href=&#34;https://github.com/umami-software/umami&#34;&gt;Umami&lt;/a&gt; 这个开源的项目，发现它可以在 &lt;a href=&#34;https://vercel.com/&#34;&gt;Vercel&lt;/a&gt; 部署，众所周知 &lt;code&gt;[Cloudfare](https://dash.cloudflare.com/)&lt;/code&gt; 和 &lt;code&gt;Vercel&lt;/code&gt; 都是大善啊🙂,我是白嫖怪(●ˇ∀ˇ●)，至于问为什么选择 &lt;code&gt;Aiven&lt;/code&gt; 不选别的，因为它给的是 &lt;code&gt;CPU：2核&lt;/code&gt; &lt;code&gt;内存：1GB&lt;/code&gt; &lt;code&gt;硬盘：5GB&lt;/code&gt; ，没办法给的太多了，还是免费，Vercel自带的也就才 &lt;code&gt;512MB&lt;/code&gt; 不大够用，这个还能提供 &lt;code&gt;迁移数据库&lt;/code&gt; 还原等，是真的香。最主要的原因就是51LA开了代理它就不生效了！！！&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;尊敬的用户，&lt;br&gt;您好，经百度统计巡查发现，您的网站yeminxi.github.io已违反您开通百度统计服务时所同意的《百度统计服务条款》 “三、使用规则：1.您在使用百度服务时，必须遵守中华人民共和国相关法律法规的规定，您同意将不会利用本服务进行任何违法或不正当的活动，包括但不限于下列行为∶7）散布淫秽、色情、赌博、暴力、凶杀、恐怖或者教唆犯罪的”。建议您着重排查欺诈、病毒木马、色情博彩相关信息。根据《百度统计服务条款》的相关条款，百度统计自即日起终止为您提供数据监控服务，您的网站数据将不再更新。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;介绍&#34;&gt;&lt;a href=&#34;#介绍&#34; class=&#34;headerlink&#34; title=&#34;介绍&#34;&gt;&lt;/a&gt;介绍&lt;/h2&gt;&lt;h3 id=&#34;Vercel&#34;&gt;&lt;a href=&#34;#Vercel&#34; class=&#34;headerlink&#34; title=&#34;Vercel&#34;&gt;&lt;/a&gt;&lt;a href=&#34;https://vercel.com/&#34;&gt;Vercel&lt;/a&gt;&lt;/h3&gt;&lt;p&gt;Vercel 是一个云平台，专注于前端框架和静态网站的部署。&lt;/p&gt;
&lt;h3 id=&#34;Aiven&#34;&gt;&lt;a href=&#34;#Aiven&#34; class=&#34;headerlink&#34; title=&#34;Aiven&#34;&gt;&lt;/a&gt;&lt;a href=&#34;https://console.aiven.io/signup?referral_code=om3btxfe3nqebmf1zlhf&#34;&gt;Aiven&lt;/a&gt;&lt;/h3&gt;&lt;p&gt;Aiven 公司提供的托管式 Google Cloud AlloyDB Omni 数据库服务。它允许用户在 Aiven 的云基础设施上轻松部署、管理和扩展 AlloyDB Omni 数据库，而无需自行管理底层基础设施。&lt;/p&gt;
&lt;h3 id=&#34;Umami&#34;&gt;&lt;a href=&#34;#Umami&#34; class=&#34;headerlink&#34; title=&#34;Umami&#34;&gt;&lt;/a&gt;&lt;a href=&#34;https://github.com/umami-software/umami&#34;&gt;Umami&lt;/a&gt;&lt;/h3&gt;&lt;p&gt;Umami 是一种简单、快速、注重隐私的 Google Analytics 替代品。&lt;/p&gt;
&lt;p&gt;详细的官方入门指南&lt;a href=&#34;https://umami.is/docs/&#34;&gt;umami.is&amp;#x2F;docs&lt;/a&gt;。&lt;/p&gt;
&lt;h2 id=&#34;准备工作&#34;&gt;&lt;a href=&#34;#准备工作&#34; class=&#34;headerlink&#34; title=&#34;准备工作&#34;&gt;&lt;/a&gt;准备工作&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;需要Github，Vercel，Aiven账号&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;第一步fork仓库或点此处一键部署&#34;&gt;&lt;a href=&#34;#第一步fork仓库或点此处一键部署&#34; class=&#34;headerlink&#34; title=&#34;第一步fork仓库或点此处一键部署&#34;&gt;&lt;/a&gt;第一步fork仓库或&lt;a href=&#34;https://vercel.com/new/clone?repository-url=https://github.com/umami-software/umami&amp;env=DATABASE_URL&#34;&gt;点此处一键部署&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;Fork仓库&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&#34;tagLink&#34;&gt;&lt;a class=&#34;link-card&#34; title=&#34;Umami&#34; href=&#34;https://github.com/umami-software/umami&#34;&gt;&lt;span class=&#34;link-card-backdrop&#34; style=&#34;background-image: url(https://api.xinac.net/icon/?url=https://github.com/umami-software/umami)&#34;&gt;&lt;/span&gt;&lt;div class=&#34;left&#34;&gt;&lt;img src=&#34;https://api.xinac.net/icon/?url=https://github.com/umami-software/umami&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://api.xinac.net/icon/?url=https://github.com/umami-software/umami&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34;/&gt;&lt;/div&gt;&lt;div class=&#34;right&#34;&gt;&lt;p class=&#34;text&#34;&gt;Umami&lt;/p&gt;&lt;p class=&#34;url&#34;&gt;Umami&lt;/p&gt;&lt;/div&gt;&lt;/a&gt;&lt;/div&gt;

&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://vercel.com/new/clone?repository-url=https://github.com/umami-software/umami&amp;env=DATABASE_URL&#34;&gt;点此处一键部署&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;第二步-注册Aiven&#34;&gt;&lt;a href=&#34;#第二步-注册Aiven&#34; class=&#34;headerlink&#34; title=&#34;第二步 注册Aiven&#34;&gt;&lt;/a&gt;第二步 注册Aiven&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;建议使用&lt;a href=&#34;https://mail.google.com/mail?hl=zh-CN&#34;&gt;谷歌邮箱&lt;/a&gt;注册，没有的话 &lt;code&gt;QQ邮箱&lt;/code&gt; 好像也没问题的，看能不能收验证链接而已。&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&#34;tagLink&#34;&gt;&lt;a class=&#34;link-card&#34; title=&#34;Aiven&#34; href=&#34;https://console.aiven.io/signup?referral_code=om3btxfe3nqebmf1zlhf&#34;&gt;&lt;span class=&#34;link-card-backdrop&#34; style=&#34;background-image: url(https://api.xinac.net/icon/?url=https://console.aiven.io/signup?referral_code=om3btxfe3nqebmf1zlhf)&#34;&gt;&lt;/span&gt;&lt;div class=&#34;left&#34;&gt;&lt;img src=&#34;https://api.xinac.net/icon/?url=https://console.aiven.io/signup?referral_code=om3btxfe3nqebmf1zlhf&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://api.xinac.net/icon/?url=https://console.aiven.io/signup?referral_code=om3btxfe3nqebmf1zlhf&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34;/&gt;&lt;/div&gt;&lt;div class=&#34;right&#34;&gt;&lt;p class=&#34;text&#34;&gt;Aiven&lt;/p&gt;&lt;p class=&#34;url&#34;&gt;注册链接&lt;/p&gt;&lt;/div&gt;&lt;/a&gt;&lt;/div&gt;

&lt;ul&gt;
&lt;li&gt;创建数据库 &lt;code&gt;MySQL&lt;/code&gt; 数据库（这里的PostgreSQL太拉了只能 &lt;code&gt;20条的请求&lt;/code&gt; ）&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;img src=&#34;https://images.418121.xyz/file/blog/play/02/01.webp&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://images.418121.xyz/file/blog/play/02/01.webp&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34; alt=&#34;创建MySQL数据库&#34;&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.418121.xyz/file/blog/play/02/02.webp&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://images.418121.xyz/file/blog/play/02/02.webp&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34; alt=&#34;选择free plan 在选择亚太地区&#34;&gt;&lt;/p&gt;
&lt;h2 id=&#34;第三步-添加环境变量&#34;&gt;&lt;a href=&#34;#第三步-添加环境变量&#34; class=&#34;headerlink&#34; title=&#34;第三步 添加环境变量&#34;&gt;&lt;/a&gt;第三步 添加环境变量&lt;/h2&gt;&lt;p&gt;复制 &lt;code&gt;Service URI&lt;/code&gt; 到 Vercel的项目里，打开项目发现是报错的，是因为没有添加环境变量。点击 &lt;code&gt;settings&lt;/code&gt; 然后再点 &lt;code&gt;environment-variables&lt;/code&gt; 添加并 &lt;code&gt;重新部署&lt;/code&gt; 即可。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.418121.xyz/file/blog/play/02/03.webp&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://images.418121.xyz/file/blog/play/02/03.webp&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34; alt=&#34;复制 Service URI 到Vercel的环境变量中添加 DATABASE_URL &#34;&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.418121.xyz/file/blog/play/02/05.webp&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://images.418121.xyz/file/blog/play/02/05.webp&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34; alt=&#34;重新部署 等待一段时间&#34;&gt;&lt;/p&gt;
&lt;h2 id=&#34;第四步-添加域名&#34;&gt;&lt;a href=&#34;#第四步-添加域名&#34; class=&#34;headerlink&#34; title=&#34;第四步 添加域名&#34;&gt;&lt;/a&gt;第四步 添加域名&lt;/h2&gt;&lt;p&gt;因为Vercel被墙，所以要配置一个域名，国内才能访问到。&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://images.418121.xyz/file/blog/play/02/06.webp&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://images.418121.xyz/file/blog/play/02/06.webp&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34; alt=&#34;绑定域名cname&#34;&gt;&lt;/p&gt;
&lt;h2 id=&#34;第五步-完成&#34;&gt;&lt;a href=&#34;#第五步-完成&#34; class=&#34;headerlink&#34; title=&#34;第五步 完成&#34;&gt;&lt;/a&gt;第五步 完成&lt;/h2&gt;&lt;p&gt;&lt;img src=&#34;https://images.418121.xyz/file/blog/play/02/07.webp&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://images.418121.xyz/file/blog/play/02/07.webp&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34; alt=&#34;部署成功&#34;&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight text&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;默认账号密码&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;账号：admin&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;密码：umami&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;可用此账号登录我的示例网站观看&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;div class=&#34;tagLink&#34;&gt;&lt;a class=&#34;link-card&#34; title=&#34;Umami&#34; href=&#34;https://um.api.418121.xyz/&#34;&gt;&lt;span class=&#34;link-card-backdrop&#34; style=&#34;background-image: url(https://api.xinac.net/icon/?url=https://um.api.418121.xyz/)&#34;&gt;&lt;/span&gt;&lt;div class=&#34;left&#34;&gt;&lt;img src=&#34;https://api.xinac.net/icon/?url=https://um.api.418121.xyz/&#34; class=&#34;lazyload placeholder&#34; data-srcset=&#34;https://api.xinac.net/icon/?url=https://um.api.418121.xyz/&#34; srcset=&#34;https://pic1.zhimg.com/v2-cd38920285d125be80b3eb504052c550_b.webp&#34;/&gt;&lt;/div&gt;&lt;div class=&#34;right&#34;&gt;&lt;p class=&#34;text&#34;&gt;Umami&lt;/p&gt;&lt;p class=&#34;url&#34;&gt;我的示例网站&lt;/p&gt;&lt;/div&gt;&lt;/a&gt;&lt;/div&gt;

&lt;p&gt;更多操作请看&lt;a href=&#34;#%E6%9C%AC%E6%96%87%E5%8F%82%E8%80%83&#34;&gt;本文参考&lt;/a&gt;&lt;/p&gt;
&lt;h1 id=&#34;结尾&#34;&gt;&lt;a href=&#34;#结尾&#34; class=&#34;headerlink&#34; title=&#34;结尾&#34;&gt;&lt;/a&gt;结尾&lt;/h1&gt;&lt;p&gt;至此，教程结束。希望对你有所帮助，有任何问题请在下方留言。可以关注我的 &lt;a href=&#34;/rss/&#34;&gt;公众号以及订阅我的文章&lt;/a&gt; ，感谢你的支持，是对我最大的动力，当然了，更多的是因为热爱。&lt;/p&gt;
&lt;h2 id=&#34;后记&#34;&gt;&lt;a href=&#34;#后记&#34; class=&#34;headerlink&#34; title=&#34;后记&#34;&gt;&lt;/a&gt;后记&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;更 新 &lt;code&gt;umami&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;打开你的fork的仓库找到 &lt;code&gt;package.json&lt;/code&gt; 文件&lt;/p&gt;
&lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;name&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;umami&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;version&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;2.15.1&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;comment&#34;&gt;//修改这一行&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;description&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;A simple, fast, privacy-focused alternative to Google Analytics.&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;author&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;Umami Software, Inc. &amp;lt;hello@umami.is&amp;gt;&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;license&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;MIT&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;homepage&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;https://umami.is&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;&amp;quot;repository&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;type&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;git&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;url&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;https://github.com/umami-software/umami.git&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

